Lemma dequeue_prev x : m_prev (MR st' x) =
  if aptr_eqb x m then None
  else if optr_eqb (m_next mr) (Some m) then m_prev (MR st x)
  else if optr_eqb (m_next mr) (Some x) then m_prev mr else m_prev (MR st x).
Proof.
