Lemma dequeue_head h' : get_head st' h' =
  if decide (h' = h) then
    (if optr_eqb (m_next mr) (Some m) then None
     else if optr_eqb (get_head st h) (Some m) then m_next mr else get_head st h)
  else get_head st h'.
Proof.
